using System.Text.Json;

namespace Gojo.Experiments.ConstructionMachines;

public static class ResponseLearningReview
{
    public static void Write(string folder)
    {
        using var study = JsonDocument.Parse(File.ReadAllText(Path.Combine(folder, "learning.json")));
        using var transfer = File.Exists(Path.Combine(folder, "observations.json")) ? JsonDocument.Parse(File.ReadAllText(Path.Combine(folder, "observations.json"))) : null;
        using var coverage = File.Exists(Path.Combine(folder, "coverage.json")) ? JsonDocument.Parse(File.ReadAllText(Path.Combine(folder, "coverage.json"))) : null;
        var data = new { study = study.RootElement, transfer = transfer is null ? null : new
        {
            methods = transfer.RootElement.GetProperty("methods"), trials = transfer.RootElement.GetProperty("trials"),
            controls = transfer.RootElement.GetProperty("cases").EnumerateArray()
                .Where(c => c.GetProperty("condition").GetString() is not ("ordinary" or "outlier"))
                .Select(c => new { title = c.GetProperty("title").GetString(), final = c.GetProperty("frames").EnumerateArray().Last().GetProperty("cost").GetDouble(),
                    unresolved = c.GetProperty("frames").EnumerateArray().Last().GetProperty("unknown").GetInt32() }).ToArray()
        }, coverage = coverage is null ? null : new { minimum = coverage.RootElement.GetProperty("minimum"), maximum = coverage.RootElement.GetProperty("maximum"),
            summaries = coverage.RootElement.GetProperty("summaries") } };
        File.WriteAllText(Path.Combine(folder, "review.html"), Template.Replace("__DATA__", JsonSerializer.Serialize(data), StringComparison.Ordinal));
    }

    private const string Template = """
