function draw(p,choice){const s=svg('svg',{viewBox:'0 0 570 260',role:'img','aria-label':'Requested displacements and the chosen bounded receiver movement'}),min=Math.min(0,...p.requests)-12,max=Math.max(0,...p.requests)+12,x=v=>32+(v-min)/(max-min)*506;
 s.append(svg('text',{x:16,y:21,fill:'#687d80','font-size':12},'Requests at the port'),svg('line',{x1:32,y1:95,x2:538,y2:95,stroke:'#d4dfd8'}),svg('line',{x1:x(0),y1:36,x2:x(0),y2:120,stroke:'#9ca9a7','stroke-dasharray':'3 3'}));
 p.requests.forEach((v,i)=>{const y=49+(i%4)*13;s.append(svg('line',{x1:x(v),y1:y,x2:x(v),y2:95,stroke:v<0?'#b44f73':'#277167',opacity:.4}));const c=svg('circle',{cx:x(v),cy:y,r:4,fill:v<0?'#b44f73':'#277167'});c.append(svg('title',{},'Request '+(i+1)+': '+v));s.append(c)});
