}
if(data.transfer){for(let i=0;i<data.transfer.methods.length;i++){const group=condition=>data.transfer.trials.filter(t=>t.method===i&&t.condition===condition),mean=(a,k)=>a.reduce((s,r)=>s+r[k],0)/a.length;const a=group('ordinary'),b=group('outlier');row($('transfer'),[data.transfer.methods[i],number(mean(a,'final')),number(mean(a,'meanDemand')),number(mean(b,'final')),number(mean(b,'meanDemand'))],i===1?'current':'')}$('transferNote').textContent=data.transfer.trials.length+' frozen-policy trajectories. Fixed receivers, unknown permissions, permitted eaves and a fixed wall are also available in the replay.'}else{$('transferNote').textContent='The separate coupled evaluation has not been generated yet.'}
if(data.coverage){$('coverageCard').hidden=false;for(const c of data.coverage.summaries)row($('coverage'),[c.condition==='ordinary'?'Cooperating parts':'Conflicting opinion',c.fixedFinal,c.rawFinal,c.guardedFinal,c.outsideCount+' / '+c.contexts]);$('coverageNote').textContent='Observed training counts: '+data.coverage.minimum+'–'+data.coverage.maximum+'. '+(data.coverage.summaries.every(c=>c.rawFinal===c.guardedFinal)?'Count qualification did not change either final result. ':'')+'Amplitudes, shared actuators and the teaching objective can still differ.'}
const histories=study.neuralSeeds.flatMap(s=>s.history),last=Math.max(...histories.map(h=>h.epoch)),lo=Math.min(...histories.map(h=>h.validation)),hi=Math.max(...histories.map(h=>h.validation)),s=svg('svg',{viewBox:'0 0 560 180',role:'img','aria-label':'Validation prediction error during neural fitting'}),seedColors=['#b57b34','#3e83a1','#277167'];
