s.append(svg('text',{x:35,y:172,fill:'#687d80','font-size':11},'Epoch 0'),svg('text',{x:480,y:172,fill:'#687d80','font-size':11},last+' epochs'),svg('text',{x:35,y:15,fill:'#687d80','font-size':11},'Validation MSE · '+mse(lo)+' to '+mse(hi)));$('curve').append(s);
study.models.forEach(m=>{row($('exports'),[m.name,m.fitSeconds.toFixed(2),m.maximumExportDifference===null?'—':mse(m.maximumExportDifference)]);const a=el('a','',m.name+' native program');a.href=m.archive;a.setAttribute('download','');$('archives').append(a)});
